"""POST HOC wrappers: preserve numerical pipeline; change IO, labels and worker partition."""
from pathlib import Path
import json,hashlib
OUT=Path(__file__).resolve().parent;PARENT=OUT.parent
source=(PARENT/'run_regional_bouts.m').read_text(encoding='utf-8')
source=source.replace('function run_regional_bouts','function posthoc_2s_run_worker(worker,totalWorkers)',1)
source=source.replace("out=fileparts(mfilename('fullpath'));root=fileparts(fileparts(out));start=tic;", "out=fileparts(mfilename('fullpath'));parent=fileparts(out);root=fileparts(fileparts(parent));start=tic;")
source=source.replace('regional_behavior_runtime.json','posthoc_2s_behavior_runtime.json')
source=source.replace("fullfile(out,'regional_xml_grouping.json')","fullfile(parent,'regional_xml_grouping.json')")
source=source.replace("addpath(out,'-begin');","addpath(parent,'-begin');addpath(out,'-begin');",1)
source=source.replace('regional_session_eligibility.csv','posthoc_2s_session_eligibility.csv').replace('regional_bouts.csv','posthoc_2s_bouts.csv').replace('regional_protocol_record.json','posthoc_2s_provenance.json')
source=source.replace('for is=1:numel(sessions)','for is=worker:totalWorkers:numel(sessions)')
source=source.replace("sprintf('regional_%s_E%d_%s_%04d_pac.mat'","sprintf('posthoc_2s_%s_E%d_%s_%04d_pac.mat'")
source=source.replace("metadata=struct('git_tag'", "metadata=struct('analysis_type',protocol.analysis_type,'post_hoc',true,'minimum_bout_s',2,'posthoc_protocol_sha256',protocol.posthoc_protocol_sha256,'worker',worker,'git_tag'")
source=source.replace("struct('animal',q.animal,'session',session,'analysis',choice.analysis", "struct('analysis_type',protocol.analysis_type,'post_hoc',true,'minimum_bout_s',2,'animal',q.animal,'session',session,'analysis',choice.analysis")
source=source.replace("assert(strcmp(metadata.protocol_sha256,protocol.protocol_sha256),'Rodent:CacheProtocol','Cache protocol mismatch');", "assert(strcmp(metadata.posthoc_protocol_sha256,protocol.posthoc_protocol_sha256)&&metadata.start_idx==b.lfp_start_idx&&metadata.stop_idx==b.lfp_stop_idx,'Rodent:CacheProtocol','POST HOC cache mismatch');")
source=source.replace("fprintf('REGIONAL %s E%d %s %d/%d status%d\\n',session,ch,b.state,ib,height(bb),features(1).status);", "if mod(ib,10)==0||ib==height(bb),fprintf('POST HOC worker%d %s E%d %s %d/%d status%d\\n',worker,session,ch,b.state,ib,height(bb),features(1).status);end")
source=source.replace("fullfile(out,'regional_bout_estimates_progress.csv')","fullfile(out,sprintf('posthoc_2s_worker%d_progress.csv',worker))")
source=source.replace("fullfile(out,'regional_bout_estimates.csv')","fullfile(out,sprintf('posthoc_2s_worker%d_estimates.csv',worker))")
source=source.replace("fullfile(out,'regional_comparator_filter_guards.csv')","fullfile(out,sprintf('posthoc_2s_worker%d_filter_guards.csv',worker))")
source=source.replace("fullfile(out,'regional_bouts_runtime.json')","fullfile(out,sprintf('posthoc_2s_worker%d_runtime.json',worker))")
source=source.replace("fullfile(out,'regional_*_pac.mat')","fullfile(out,'posthoc_2s_*_pac.mat')")
source=source.replace("status=struct('status','COMPLETE'", "status=struct('analysis_type',protocol.analysis_type,'post_hoc',true,'worker',worker,'status','COMPLETE'")
source=source.replace("struct('status','FAILED_STOP'", "struct('analysis_type',protocol.analysis_type,'post_hoc',true,'worker',worker,'status','FAILED_STOP'")
(OUT/'posthoc_2s_run_worker.m').write_text('% POST HOC 2-s sensitivity; frozen method helpers unchanged.\n'+source,encoding='utf-8')

stats=(PARENT/'compute_regional_statistics.py').read_text(encoding='utf-8')
stats=stats.replace('"""Prespecified statistics for regional channels and revised tracking-rate bouts."""','"""POST HOC 2-s statistics; same estimators and seed scheme as 5-s pipeline."""')
stats=stats.replace("ROOT=Path(r'C:\\Users\\nghare\\.brainstorm\\process'); OUT=ROOT/'revision_checks/rodent_multi'", "ROOT=Path(r'C:\\Users\\nghare\\.brainstorm\\process'); OUT=Path(__file__).resolve().parent; PARENT=OUT.parent")
stats=stats.replace("read(OUT/'regional_xml_grouping.json')","read(PARENT/'regional_xml_grouping.json')")
stats=stats.replace('regional_bouts_runtime.json','posthoc_2s_bouts_runtime.json').replace('regional_bout_estimates.csv','posthoc_2s_bout_estimates.csv').replace('regional_protocol_record.json','posthoc_2s_provenance.json')
stats=stats.replace("'stage':'regional rodent statistics'","'stage':'POST HOC 2-s regional statistics'")
stats=stats.replace("frame=pd.DataFrame(rows);frame['git_commit']", "frame=pd.DataFrame(rows);frame['analysis_type']=metadata['analysis_type'];frame['post_hoc']=True;frame['minimum_bout_s']=2;frame['git_commit']")
stats=stats.replace("('regional_'+name)","('posthoc_2s_'+name)").replace('regional_statistics_runtime.json','posthoc_2s_statistics_runtime.json')
(OUT/'posthoc_2s_statistics.py').write_text(stats,encoding='utf-8')

mixed=(PARENT/'fit_regional_mixed_models.m').read_text(encoding='utf-8')
mixed=mixed.replace('function fit_regional_mixed_models','function posthoc_2s_fit_mixed_models',1)
mixed=mixed.replace('regional_bouts_runtime.json','posthoc_2s_bouts_runtime.json').replace('regional_protocol_record.json','posthoc_2s_provenance.json').replace('regional_bout_estimates.csv','posthoc_2s_bout_estimates.csv')
mixed=mixed.replace("meta.stage='region-specific REML mixed models'","meta.stage='POST HOC 2-s region-specific REML mixed models'")
mixed=mixed.replace("C.analysis=repmat(analysis,height(C),1);", "C.analysis=repmat(analysis,height(C),1);C.analysis_type=repmat(string(meta.analysis_type),height(C),1);C.post_hoc=true(height(C),1);C.minimum_bout_s=repmat(2,height(C),1);")
mixed=mixed.replace('regional_mixed_','posthoc_2s_mixed_').replace('regional_mixed_models','posthoc_2s_mixed_models').replace("fprintf('MIXED ","fprintf('POST HOC MIXED ")
(OUT/'posthoc_2s_fit_mixed_models.m').write_text('% POST HOC 2-s sensitivity; model specification unchanged.\n'+mixed,encoding='utf-8')
meta=json.loads((OUT/'posthoc_2s_provenance.json').read_text(encoding='utf-8'))
manifest={name:hashlib.sha256((PARENT/name).read_bytes()).hexdigest() for name in ['run_regional_bouts.m','compute_regional_statistics.py','fit_regional_mixed_models.m','v1_bout_features.m']}
(OUT/'posthoc_2s_wrapper_sources.json').write_text(json.dumps(dict(analysis_type=meta['analysis_type'],post_hoc=True,metadata=meta,prespecified_wrapper_sha256=manifest),indent=2),encoding='utf-8')
print('POST HOC wrappers generated; numerical helpers and specifications unchanged')
